  "components": {
    "schemas": {
      "RaitCase": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "format": "uuid",
            "default": "gen_random_uuid()"
          },
          "tenant_id": {
            "type": "string",
            "format": "uuid"
          },
          "ait_id": {
            "type": "string",
            "format": "uuid"
          },
          "origin_case_id": {
            "type": "string",
            "format": "uuid",
            "nullable": true
          },
          "protocol_number": {
            "type": "string",
            "maxLength": 40
          },
          "instance": {
            "type": "string",
            "maxLength": 20,
            "enum": ["defesa_previa", "jari", "cetran"]
          },
          "circuit": {
            "type": "integer"
          },
          "state": {
            "type": "string",
            "maxLength": 40,
            "enum": [
              "PROTOCOLADO",
              "TRIAGEM_ADMISSIBILIDADE",
              "NAO_CONHECIDO",
              "ADMITIDO",
              "AGUARDANDO_REMESSA_JARI",
              "DISTRIBUIDO",
              "EM_INSTRUCAO",
              "DILIGENCIA",
              "PRONTO_P_DECISAO",
              "DECIDIDO_AUTORIDADE",
              "PAUTADO",
              "JULGADO_SESSAO",
              "COMUNICADO",
              "TRANSITADO",
              "REMETIDO_2A_INSTANCIA",
              "ENCERRADO_DESISTENCIA"
            ],
            "default": "'PROTOCOLADO'"
          },
          "intake_channel": {
            "type": "string",
            "maxLength": 30
          },
          "protocolled_at": {
            "type": "string",
            "format": "date-time"
          },
          "admitted_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "judge_body_received_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "judge_body_received_on": {
            "type": "string",
            "format": "date",
            "nullable": true
          },
          "cetran_received_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "cetran_received_on": {
            "type": "string",
            "format": "date",
            "nullable": true
          },
          "remitted_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "decided_at": {
            "type": "string",
            "format": "date-time",
            "nullable": true
          },
          "communicated_at": {
